select * from jsonb_populate_recordset(null::public.temples, $rtam$[{"id":"d0d8a0cc-faf9-4092-9439-8ffcc5b3d040","name":"Kurmanathaswamy temple, Srikurmam","deity":"Vishnu as Kurmanatha (Kurma avatar)","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Andhra Pradesh","district":"Srikakulam","town":"Sri Kurmam","latitude":18.27,"longitude":84.0066,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Vamsadhara River","river_distance_km":8.6,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T10:59:23.880063+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A temple in Srikurmam village, Srikakulam district, dedicated to Vishnu's tortoise avatar and his consort Lakshmi as Kurmanayaki. An early inscription records that the Eastern Ganga king Anantavarman Chodaganga converted it from a Shiva temple to a Vaishnava one. It is the only known pre-14th-century temple devoted to the Kurma avatar.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Alluri Sitarama Raju International Airport","nearest_airport_distance_km":62.1,"nearest_railway_station_name":"Urlam railway station","nearest_railway_distance_km":18.4,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Kurmanathaswamy temple, Srikurmam), summarised; location via OpenStreetMap","architecture_style":"Fusion of Kalinga and Dravidian styles","construction_century":11},{"id":"d10c598e-b2ac-4dde-9c2d-77bc5a66814c","name":"Pushkar Brahma Temple","deity":"Brahma","sampradaya":"Smartha","significance":[],"country":"India","state":"Rajasthan","district":"Ajmer","town":"Pushkar","latitude":26.4899,"longitude":74.5511,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pushkar Lake","river_distance_km":0.1,"best_season_notes":"Oct–Nov for the Pushkar Camel Fair and Kartik Purnima bathing; cooler Nov–Feb otherwise.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T20:39:31.59741+00:00","updated_at":"2026-11-04T11:30:32.947142+00:00","sthala_purana":"One of the very few Brahma temples in India. Tradition holds Brahma dropped a lotus (pushpa) to earth, and it fell here, creating Pushkar Lake; he then performed a yajna on its banks, but forgot to invite his wife Saraswati and married the local milkmaid Gayatri to complete the rite in time, drawing a curse that he be worshipped almost nowhere else.","etiquette_notes":null,"native_name":"पुष्कर ब्रह्मा मन्दिर","morning_opens_at":"06:00:00","morning_closes_at":"13:30:00","evening_opens_at":"15:00:00","evening_closes_at":"20:30:00","timings_notes":"Summer hours extend slightly later at both ends (6am–9pm); around Kartik Purnima and the Pushkar Mela, expect longer hours and heavy crowds.","accessibility_notes":null,"nearest_airport_name":"Ajmer (Kishangarh) Airport","nearest_airport_distance_km":27,"nearest_railway_station_name":"Pushkar Railway Station","nearest_railway_distance_km":4,"emergency_contact_notes":null,"sthala_purana_source":null,"architecture_style":"Marble and stone with red shikhara","construction_century":14},{"id":"d1124046-5698-4117-afde-1a3d98ce7bb0","name":"Parumala Valiya Panayannarkavu Devi Temple","deity":"Bhadrakali and Shiva","sampradaya":"Shakta","significance":[],"country":"India","state":"Kerala","district":"Pathanamthitta","town":"Kadapra","latitude":9.33231,"longitude":76.53723,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pampa","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:59.708182+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"An ancient temple on the bank of the Pampa river at Parumala, Pathanamthitta, Kerala, dedicated to Bhadrakali and Shiva. It is regarded as one of the three most important Bhadrakali temples in Kerala and is mentioned in classic Malayalam literature. According to folklore, Parasurama installed the Shiva image and the sages Durvasa and Narada the goddess.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":92.6,"nearest_railway_station_name":"Chengannur railway station","nearest_railway_distance_km":8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Parumala Valiya Panayannarkavu Devi Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"d1a77598-79fc-49dd-8910-71a55218b4ba","name":"Sri Sri Kalika Maharani Temple","deity":"Kali","sampradaya":"Shakta","significance":[],"country":"India","state":"Jharkhand","district":"Bokaro","town":"Chas","latitude":23.65593,"longitude":86.17942,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Garga River","river_distance_km":0.7,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null