,"architecture_style":null,"construction_century":18},{"id":"d2faff68-3499-4a77-8a58-281a2f4260c1","name":"Sundha Mata Temple","deity":"Chamunda","sampradaya":"Shakta","significance":[],"country":"India","state":"Rajasthan","district":"Jalore","town":"Dantlawas","latitude":24.833,"longitude":72.367,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Sagi River","river_distance_km":2.2,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:27.898205+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A hilltop temple of the goddess Chamunda on Sundha hill in Jalore district, Rajasthan. It is believed to be more than 900 years old, and is said to have been built by the Deval Pratiharas with help from the Chauhans of Jalore.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Maharana Pratap Airport","nearest_airport_distance_km":156.7,"nearest_railway_station_name":"Malwara railway station","nearest_railway_distance_km":10.4,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Sundha Mata Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"d31248e3-a45e-4c81-8a83-967873ba7550","name":"Garibnath Temple","deity":"Shiva as Garibnath (Garibeshwara)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Bihar","district":"Muzaffarpur","town":"Muzaffarpur","latitude":26.12444,"longitude":85.39028,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Burhi Gandak River","river_distance_km":1.4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:05:20.030396+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"One of the older Shiva temples in Muzaffarpur, Bihar, nicknamed the Deoghar of Bihar. The presiding deity is Garibnath, also called Garibeshwara, meaning Lord of the poor. Prayers in the month of Sawan are held to be especially meaningful, and the temple is very crowded then.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Muzzafarpur Airport","nearest_airport_distance_km":7.7,"nearest_railway_station_name":"Muzaffarpur Junction railway station","nearest_railway_distance_km":1.2,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Garibnath Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"d31e01fb-0222-42fb-ae05-2f65d96e272a","name":"Simhachalam Varaha Narasimha Temple","deity":"Varaha Narasimha","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Andhra Pradesh","district":"Visakhapatnam","town":"Simhachalam","latitude":17.7665,"longitude":83.2508,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Simhachalam Devasthanam annadanam hall — free meals served to pilgrims daily","food_source_contact":null,"food_distance_km":0,"nearest_river_name":"Meghadri Gedda River","river_distance_km":5.7,"best_season_notes":"Nov–Feb. Simhachalam sits inland of Visakhapatnam, so it is less cyclone-exposed than the immediate coast, but still sees the same Bay of Bengal storm season taper off by November.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T13:44:40.752775+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"The deity here combines the Varaha and Narasimha avataras, and is coated in sandalwood paste throughout the year. Only on Chandanotsavam (Akshaya Tritiya) is the paste removed and the original form shown, an event that draws very large crowds.","etiquette_notes":null,"native_name":"సింహాచలం వరాహ నరసింహ స్వామి ఆలయం","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Alluri Sitarama Raju International Airport","nearest_airport_distance_km":35.7,"nearest_railway_station_name":"Gopalapatnam railway station","nearest_railway_distance_km":3.5,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":"Kalinga/Odisha-influenced Dravidian, with later Vijayanagara-era additions","construction_century":11},{"id":"d3721de7-71b0-4a90-a62b-9bed9c4b89d6","name":"Paippad Puthenkavu Bhagavathi Temple","deity":"Bhagavathi","sampradaya":"Shakta","significance":[],"country":"India","state":"Kerala","district":"Kottayam","town":"Nalukody","latitude":9.42175,"longitude":76.56733,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Manimala River","river_distance_km":6.5,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:59.708182+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An ancient Bhagavathi shrine at Paippad, about 5 km from Changanacherry in Kottayam, Kerala. Its annual festival falls on Bharani day in the month of Meenam, and the Kalamezuthu and Pattu procession is a key part of local celebrations. Makarabharani Pongala is a notable offering, and the temple is run by an elected Devaswom committee of two NSS Karayogams.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Cochin International Airport","nearest_airport_distance_km":83.4,"nearest_railway_station_name":"Thiruvalla railway station","nearest_railway_distance_km":3.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Paippad Puthenkavu Bhagavathi Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"d375cfdd-01cf-4965-870d-42adf0c08c85","name":"Tara Tarini Temple, Ganjam","deity":"Tara Tarini (Devi)","sampradaya":"Shakta","significance":["Shakti Peetha"],"country":"India","state":"Odisha","district":"Ganjam","town":"Purushottampur","latitude":19.3667,"longitude":84.7833,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Rushikulya","river_distance_km":0.5,"best_season_notes":"Mar–Apr for the four Tuesday fairs in the Odia month of Chaitra; otherwise Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T13:57:28.972216+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"Set on the Kumari hills above the Rushikulya river, one of the four major Adi Shakti Peethas of Odisha, where tradition holds Sati's breasts fell. A separate, more local tradition credits a Brahmin named Basu Praharaj with establishing the shrine after the goddess appeared in his dream. The site has long been associated with tantric worship alongside its Shakta tradition.","etiquette_n