arest_airport_name":"Chennai International Airport","nearest_airport_distance_km":16.1,"nearest_railway_station_name":"Vandalur railway station","nearest_railway_distance_km":5.7,"emergency_contact_notes":null,"sthala_purana_source":"Contributor-submitted local survey","architecture_style":null,"construction_century":null},{"id":"d9062a23-e690-45f5-8b5f-b947e0a11a2e","name":"Draksharamam Bhimeswara Temple","deity":"Bhimeswara (Shiva) / Manikyamba (Devi)","sampradaya":"Shaiva","significance":["Pancharama Kshetra","Shakti Peetha","Trilinga Kshetra"],"country":"India","state":"Andhra Pradesh","district":"Konaseema","town":"Draksharamam","latitude":16.9333,"longitude":82.05,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Pangiri cheruvu kalava River","river_distance_km":12.9,"best_season_notes":"Feb–Mar for Maha Shivaratri; otherwise Oct–Feb.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T17:30:52.99453+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"One of the five Pancharama Kshetras: tradition holds Shiva's linga, worn at his throat, shattered into five pieces during the slaying of the demon Tarakasura, each piece consecrated at a different site, this being one. A separate tradition ties the site to Daksha's yajna, at which Sati is said to have self-immolated — no formal yajna is performed here even now as a result. Inscriptions here reach back to the 11th century, with the site's core traced to the 9th-10th century Eastern Chalukyas. The goddess is worshipped here as Manikyamba, and the site is counted among the Ashtadasha Shakti Peethas.","etiquette_notes":null,"native_name":"ద్రాక్షారామ భీమేశ్వర ఆలయం","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"tim