ses_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Lal Bahadur Shastri International Airport","nearest_airport_distance_km":85.9,"nearest_railway_station_name":"Muthani railway station","nearest_railway_distance_km":4,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":"Early Nagara, octagonal plan","construction_century":2},{"id":"deeeab53-b876-401c-99c7-00873f5302b4","name":"Shiv Mandir, Ambarnath","deity":"Shiva as Ambreshwar","sampradaya":"Shaiva","significance":[],"country":"India","state":"Maharashtra","district":"Thane","town":"Ambernath","latitude":19.1986,"longitude":73.1766,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Waldhuni","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:53.924452+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"An 11th-century stone Shiva temple beside the Waldhuni river near Ambarnath, built in 1060 CE and probably by the Shilahara king Chhittaraja. Unusually, its sanctum lies below ground, reached by about 20 steps and open to the sky, since the tower seems never to have been finished. It is of Bhumija form.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Navi Mumbai International Airport","nearest_airport_distance_km":25.9,"nearest_railway_station_name":"Ambarnath railway station","nearest_railway_distance_km":1.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Shiv Mandir, Ambarnath), summarised; location via OpenStreetMap","architecture_style":"Bhumija","construction_century":11},{"id":"df65e8ca-7ad3-4970-8d04-d9682a7b61db","name":"Andalurkavu","deity":"Rama","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Kerala","district":"Kannur","town":"Dharmadom","latitude":11.7947,"longitude":75.4772,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dharmadam River","river_distance_km":0.5,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:13:52.370722+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"An ancient Thiyyar community temple at Andalur in Dharmadam village, Kannur, dedicated to Rama, with its main festival in the Malayalam month of Kumbam. A custom here offers a small bow and arrow in the name of each newborn Thiyyar boy, giving the shrine its name, the Thousand Bows of Andalur.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Kannur International Airport","nearest_airport_distance_km":15.5,"nearest_railway_station_name":"Etakkot railway station","nearest_railway_distance_km":3.9,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Andalurkavu), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"df73371b-aea6-4f78-ada6-d6d1c5c4f632","name":"Peddamunigal","deity":"Bhavani","sampradaya":"Shakta","significance":[],"country":"India","state":"Telangana","district":"Nalgonda","town":"Neredugommu mandal","latitude":16.57859,"longitude":79.07056,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Krishna","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:47.875457+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"Peddamunigal, also called Munigal, is a temple in Nalgonda district, Telangana, set on the banks of the Krishna River behind the Nagarjuna Sagar Dam and surrounded by the Nallamala forest. It is described as the abode of the goddess Bhavani. The article also draws a comparison with Tuljapur and its Tulja Bhavani shrine.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Rajiv Gandhi International Airport","nearest_airport_distance_km":99.4,"nearest_railway_station_name":"Macherla railway station","nearest_railway_distance_km":41.1,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Peddamunigal), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"df82ae14-85da-4588-96b7-9507a787505f","name":"Veerateeswarar Temple, Thirukovilur","deity":"Shiva as Veerateeswarar","sampradaya":"Shaiva","significance":[],"country":"India","state":"Tamil Nadu","district":"Kallakurichi","town":"Tirukkovilur","latitude":11.97139,"longitude":79.21056,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Ponnaiyar River","river_distance_km":0.3,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:38.937899+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Tevaram-praised Shiva temple in Tirukoilur with Parvathi as Periyanayagi, believed to be a 10th-century Chola work. Granite walls enclose it, and two three-tiered gopurams serve the two main shrines. Major festivals include Masimaham, Karthigai Somavaram and the Manickavasagar festival.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Stated hours: 6 am to 12 pm and 4 pm to 8:30 pm daily; open all day on new moon days.","accessibility_notes":null,"nearest_airport_name":"Neyveli Airport","nearest_airport_distance_km":52.7,"nearest_railway_station_name":"Tirukkovilur railway station","nearest_railway_distance_km":1.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Veerateeswarar Temple, Thirukovilur), summarised; location via OpenStreetMap","architecture_style":"Dravidian","construction_century":10},{"id":"dfe1c6ff-2ad6-4348-adf6-c0e2623cc318","name":"Gokarna Mahabaleshwar Temple","deity":"Mahabaleshwara (Shiva)","sampradaya":"Shaiva","significance":[],"country":"India","state":"Karnataka","district":"Uttara Kannada","town":"Gokarna","latitude":14.55,"longitude":74.3167,"sandhya_friendly":"yes","sandhya_notes":"The temple sits close to the town's beach and bathing ghats on the Arabian Sea.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Amrutanna Prasad Bhojana — free meals served twice daily, roughly noon–2pm and 7:30–8:30pm","food_source_contact":null,"food_distance_km":0.2,"nearest_river_name":"Aghanashini River","river_distance_km":5.5,"best_season_notes":"Oct–Mar; the Western Ghats here get very heavy southwest-monsoon rain from June to September, so the shoulder months just after it clears (Oct–Nov) are lush and green without the downpours.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"creat