:null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Chennai International Airport","nearest_airport_distance_km":9.9,"nearest_railway_station_name":"Kodambakkam railway station","nearest_railway_distance_km":0.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Mahalingapuram Ayyappan Temple), summarised; location via OpenStreetMap","architecture_style":"Kerala style","construction_century":20},{"id":"e1dbce6d-86e2-4621-91bf-ec2f20508cb3","name":"Pitambara Peeth, Datia","deity":"Bagalamukhi (Devi)","sampradaya":"Shakta","significance":[],"country":"India","state":"Madhya Pradesh","district":"Datia","town":"Datia","latitude":25.67,"longitude":78.47,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Angori Nadi River","river_distance_km":9,"best_season_notes":"Oct–Mar, avoiding peak central-India summer heat.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-05T08:35:20.91066+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A major Shakta pilgrimage complex in the Sonagiri hills dedicated to Bagalamukhi, one of the ten Mahavidyas (wisdom-goddess forms of Devi), worshipped here for her power of stambhana — the paralysis of hostile forces. The complex holds 77 shrines on the hill and a further 26 in the village below, including a Dhumavati temple and a Shivalinga, Vankhandeswar, whose installation local tradition traces back to the era of the Mahabharata.","etiquette_notes":null,"native_name":"पीताम्बरा पीठ","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Datia Airstrip","nearest_airport_distance_km":4.1,"nearest_railway_station_name":"Datia railway station","nearest_railway_distance_km":3.6,"emergency_contact_notes":null,"sthala_purana_source":"Local/regional tradition","architecture_style":null,"construction_century":null},{"id":"e2495822-d631-4565-bd28-e63d92fda368","name":"Laxminarayan Temple (Birla Mandir), Delhi","deity":"Lakshmi and Narayana (Vishnu)","sampradaya":"Vaishnava","significance":[],"country":"India","state":"Delhi","district":"Central Delhi","town":"New Delhi","latitude":28.6328,"longitude":77.1989,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Yamuna River","river_distance_km":5.3,"best_season_notes":"Janmashtami and Diwali draw the largest crowds.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-25T13:54:12.118115+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Built between 1933 and 1939 by the industrialist Jugal Kishore Birla with his father Baldeo Das Birla; the foundation stone was laid by Maharaj Udaybhanu Singh. Gandhi inaugurated the temple in 1939 on the condition that people of all castes be admitted.","etiquette_notes":"Photography, mobile phones and cameras are not allowed inside the temple.","native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Per Delhi Tourism (a tourism source, not the temple's own schedule): roughly 4:30am–1:30pm and 2:30–9pm; free entry.","accessibility_notes":null,"nearest_airport_name":"Indira Gandhi International Airport","nearest_airport_distance_km":13.1,"nearest_railway_station_name":"New Delhi railway station","nearest_railway_distance_km":2.5,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Laxminarayan Temple); Delhi Tourism","architecture_style":"Nagara (northern) style","construction_century":20},{"id":"e26a6138-13f8-4e92-8dfb-c7706b32b046","name":"Bhubaneswari Temple","deity":"Bhubaneswari","sampradaya":"Shakta","significance":[],"country":"India","state":"Tripura","district":"Gomati","town":"Udaipur","latitude":23.529,"longitude":91.505,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Gomati River","river_distance_km":0.4,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:36.086063+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Bhubaneswari Temple is in Rajnagar, Tripura, about 55 km from Agartala. It is believed to have been built between 1660 and 1675 and stands beside the palace of Maharaja Govinda Manikya. Rabindranath Tagore mentions it in his work.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Maharaja Bir Bikram Airport","nearest_airport_distance_km":48.3,"nearest_railway_station_name":"Udaipur railway station","nearest_railway_distance_km":3.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Bhubaneswari Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":17},{"id":"e26ad1b4-da35-41cc-8f0d-d02fac1d264b","name":"Trikoteswara Swamy Temple, Kotappakonda","deity":"Shiva (Trikoteswara, \"Lord of the Three Peaks\")","sampradaya":"Shaiva","significance":[],"country":"India","state":"Andhra Pradesh","district":"Palnadu","town":"Kotappakonda","latitude":16.145,"longitude":80.039,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Vogaru Vagu River","river_distance_km":2.6,"best_season_notes":"Its Maha Shivaratri jatara features the \"Prabha\" festival, giant illuminated towers over 100 feet tall built by village communities.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T08:36:33.433509+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"Temple inscriptions show a shrine existed here before 1172 CE, on a hill also called Trikutadri or Trikuta Parvatham (\"hill of three peaks\"). It saw patronage from the Eastern Chalukyas and Kakatiyas between roughly the 9th and 14th centuries, and significant building activity under Vijayanagara rule in the 14th–16th centuries; local tradition also credits a notable 1761 renovation, though that date rests on local rather than academic sources. The temple is today administered by the Tirumala Tirupati Devasthanams (TTD).","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Vijayawada Airport","nearest_airport_distance_km":92.2,"nearest_railway_station_name":"Munumaka railway station","nearest_railway_distance_km":8,"emergency_contact_notes":null,"sthala_purana_source":"Temple inscriptions; local tradition","architecture_style":"Dravidian; hilltop shrine with medieval-to-Vijayanagara-era construction phases","construction_century":12},{"id":"e277c01b-bf9f-48f4-a638-b1bd7632e172","name":"Shani Shingnapur Temple","deity":"Shani","sampradaya":null,"significance":[],"country":"India","state":"Maharashtra","district":"Ahmednagar","town":"Shani Shingnapur","latitude":19.6033,"longitude":74.7573,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Panasnala River","river_distance_km":null,"best_season_notes":"Oct–Feb; Saturdays (Shani's day) and Amavasya draw the largest crowds.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-04T13:57:28.972216+00:00","updated_at":"2026-09-30T13:12:14.428399+00:00","sthala_purana":"Legend holds that after a flood, villagers found a large black stone (svayambhu, self-manifested) floating in the Panasnala stream; when a shepherd struck it with a stick, it reportedly bled, and the stone was installed in the village as the deity Shani.","etiquette_notes":"The entire village is well known for having no doors or locks on homes or shops (including the local bank branch), reflecting communal faith in the deity's protection — a village-wide custom, not a temple rule.","native_name":"श्री शनि शिंगणापूर मंदिर","morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":"Sources disagree: one gives 7am–8:30pm, another describes it as open 24 hours (consistent with there being no doors to close). Flagged, not resolved.","accessibility_notes":null,"nearest_airport_name":"Chhatrapati Sambhajinagar (Aurangabad) Airport","nearest_airport_distance_km":90,"nearest_railway_station_name":"Rahuri railway station","nearest_railway_distance_km":32,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Shani Shingnapur)","architecture_style":"Not a conventional built temple — a 5.5 ft black rock stands on an open platform with no roof, doors or surrounding walls; a trishul stands beside it and a Nandi faces it from the south, with mustard oil poured continuously over the idol from a suspended vessel","construction_century":null},{"id":"e2d8ab56-8fef-4834-905a-40e86246b81e","name":"Shri Alkheswar Mahadev Mandir","deity":"Shiva as Alkheshwar Mahadev","sampradaya":"Shaiva","significance":[],"country":"India","state":"Uttar Pradesh","district":"Mathura","town":"Bera","latitude":27.81299,"longitude":77.76953,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Yamuna River","river_distance_km":6.6,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:38:36.086063+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"This temple in Bera village, Mathura district, Uttar Pradesh, honours Alkheshwar Mahadev, known locally as Alakh Baba. According to the article, it was constructed in ancient times by a person named Jayas.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Noida International Airport","nearest_airport_distance_km":42.8,"nearest_railway_station_name":"Vrindavan railway station","nearest_railway_distance_km":27.3,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Shri Alkheswar Mahadev Mandir), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"e352fe01-a3b0-423d-b6ca-31010e8b7745","name":"Basistha Temple","deity":"Shiva","sampradaya":"Shaiva","significance":[],"country":"India","state":"Assam","district":"Kamrup Metropolitan","town":"Basistha Chariali","latitude":26.095,"longitude":91.78444,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Basistha and Bahini (Bharalu) rivers","river_distance_km":null,"best_season_n