arest_railway_distance_km":8.4,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Maa Ratneshwari Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"ebd8bff9-fbfe-4dc1-88d0-b176401e1246","name":"Chhinnamastika Temple, Rajrappa","deity":"Chhinnamasta (Devi, one of the ten Mahavidyas)","sampradaya":"Shakta","significance":["Tantric shrine"],"country":"India","state":"Jharkhand","district":"Ramgarh","town":"Rajrappa","latitude":23.63222,"longitude":85.69389,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Damodar (confluence with the Bhairavi)","river_distance_km":0.1,"best_season_notes":"Busiest at Makar Sankranti (mid-Jan), Maha Shivaratri and Vijayadashami, and on every full and new moon.","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-22T08:39:44.697229+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"Set at the confluence of the Damodar and Bhairavi rivers, this is a recognised centre of Chhinnamasta worship, one of the ten tantric Mahavidyas, depicted self-decapitated and holding her own severed head. Unusually, the deity is represented not by a carved idol but by a natural rock covered in an ashtadhatu (eight-metal alloy) kavacha. The site's association with tantric and tribal worship is old, and it was well established as a centre of Chhinnamasta worship by the 18th century, though an exact founding date is not reliably documented.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Ranchi Birsa Munda Airport","nearest_airport_distance_km":51.9,"nearest_railway_station_name":"Barkipona railway station","nearest_railway_distance_km":8.6,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia; local tradition","architecture_style":"Tantric-style temple architecture","construction_century":null},{"id":"ec2f1e93-179c-47b6-b955-0e6dc99f553e","name":"Baidyanath Temple","deity":"Shiva as Baidyanath","sampradaya":"Shaiva","significance":[],"country":"India","state":"Jharkhand","district":"Deoghar","town":"Deoghar","latitude":24.4925,"longitude":86.7,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Dhadhwa River","river_distance_km":3.1,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:24.13334+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A Shiva temple in Deoghar, Jharkhand, with a central shrine of Baba Baidyanath and 21 other temples in the complex. It is regarded as one of the twelve Jyotirlingas.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Deoghar International Airport","nearest_airport_distance_km":5.1,"nearest_railway_station_name":"Baidyanathdham railway station","nearest_railway_distance_km":0.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Baidyanath Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"ecb19034-b752-488b-a436-8d7178e17383","name":"Mahakaleshwar Jyotirlinga, Ujjain","deity":"Shiva (Mahakaleshwar)","sampradaya":null,"significance":["Jyotirlinga","Sapta Puri"],"country":"India","state":"Madhya Pradesh","district":"Ujjain","town":"Ujjain","latitude":23.1828,"longitude":75.7681,"sandhya_friendly":"yes","sandhya_notes":"Ram Ghat on the Shipra, a short walk from the temple, is the traditional bathing and ritual spot.","samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"pure_veg_available","food_source_name":"Shri Mahakaleshwar Annakshetra — free meals since 2004, serving several thousand devotees daily","food_source_contact":null,"food_distance_km":0.2,"nearest_river_name":"Shipra","river_distance_km":0.8,"best_season_notes":"Oct–Mar, with Dec–Jan bringing thick fog to the Malwa plateau some mornings; extremely crowded during Simhastha Kumbh (every 12 years).","submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-09-03T11:51:56.898831+00:00","updated_at":"2026-09-05T19:02:16.315601+00:00","sthala_purana":"The lingam here is svayambhu and faces south, the only Jyotirlinga to do so, which gives it the name Dakshinamukhi. Tradition relates that Shiva emerged from it to destroy the asura Dushana who was persecuting the devotees of Ujjain. The daily Bhasma Aarti, offered with sacred ash before dawn, is unique to this temple.","etiquette_notes":null,"native_name":"महाकालेश्वर ज्योतिर्लिंग","morning_opens_at":"02:30:00","morning_closes_at":"11:00:00","evening_opens_at":"17:00:00","evening_closes_at":"22:00:00","timings_notes":"The Bhasma Aarti (pre-dawn ash offering) around 4am is the signature ritual here and needs separate advance booking.","accessibility_notes":null,"nearest_airport_name":"Devi Ahilya Bai Holkar Airport, Indore","nearest_airport_distance_km":55,"nearest_railway_station_name":"Ujjain Junction","nearest_railway_distance_km":3,"emergency_contact_notes":null,"sthala_purana_source":"Shiva Purana / Skanda Purana (Jyotirlinga tradition)","architecture_style":"Bhumija, with Maratha and Chalukya influences; the present five-storey structure was rebuilt after Iltutmish's destruction","construction_century":18},{"id":"ed1b4749-24fe-4208-8bfb-aced462ab59f","name":"Bhattarika Temple","deity":"Bhattarika (Durga, as Shakti)","sampradaya":"Shakta","significance":[],"country":"India","state":"Odisha","district":"Cuttack","town":"Badamba","latitude":20.36853,"longitude":85.27171,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Mahanadi","river_distance_km":null,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:05:20.030396+00:00","updated_at":"2026-11-04T12:15:00.624755+00:00","sthala_purana":"On the bank of the Mahanadi at Sasanga village in Cuttack district, this shrine honours the goddess Bhattarika as a form of Shakti. According to tradition, Durga appeared here to lend strength to Parashurama. Pana Sankranti, Akshaya Tritiya, Dussehra and an annual Durga Puja are celebrated.","etiquette_notes":null,"native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Biju Patnaik International Airport","nearest_airport_distance_km":57.9,"nearest_railway_station_name":"Bolagarh Road railway station","nearest_railway_distance_km":22.7,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Bhattarika Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null},{"id":"ed783ed8-d49a-4b6e-88e3-ee4c5d0fcda5","name":"Elai Kaatha Amman Temple","deity":"Ezhai Kaatha Amman","sampradaya":"Shakta","significance":[],"country":"India","state":"Tamil Nadu","district":"Madurai","town":"Melur","latitude":9.99747,"longitude":78.40826,"sandhya_friendly":"unknown","sandhya_notes":null,"samidhadhanam_friendly":"unknown","samidhadhanam_notes":null,"food_tier":"unknown","food_source_name":null,"food_source_contact":null,"food_distance_km":null,"nearest_river_name":"Uppaar River","river_distance_km":8.3,"best_season_notes":null,"submitted_by":null,"status":"approved","verified_by":null,"moderator_note":null,"created_at":"2026-11-04T11:04:53.924452+00:00","updated_at":"2026-11-05T02:38:03.965515+00:00","sthala_purana":"A village goddess temple near Melur in Madurai district, associated with the Vellalur Nadu communities, who regard the goddess and Valladikaarar as sister and brother. Her festival is held in September, with a 15-day observance of vegetarian eating and no construction. Seven young girls are chosen as her daughters for the period.","etiquette_notes":"During the festival, local people observe a 15-day period of vegetarian food, avoiding meat and flour-based foods, and no construction work.","native_name":null,"morning_opens_at":null,"morning_closes_at":null,"evening_opens_at":null,"evening_closes_at":null,"timings_notes":null,"accessibility_notes":null,"nearest_airport_name":"Madurai International Airport","nearest_airport_distance_km":39.2,"nearest_railway_station_name":"Sivaganga railway station","nearest_railway_distance_km":18.8,"emergency_contact_notes":null,"sthala_purana_source":"Wikipedia (Elai Kaatha Amman Temple), summarised; location via OpenStreetMap","architecture_style":null,"construction_century":null}]$rtam$::jsonb)
